<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#E3301E;
    --blue:#1B3FA0;
    --yellow:#F2C500;
    --black:#111111;
    --white:#FFFFFF;
    --grey:#EDEDED;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:'Archivo',Helvetica,Arial,sans-serif;
    color:var(--black);
    background:var(--white);
    line-height:1.55;
  }
  .grid-line{background:var(--black)}

  /* ---------- header: the picture ---------- */
  header{
    min-height:100vh;
    display:grid;
    grid-template-columns:1fr 1fr;
    grid-template-rows:auto 1fr auto;
    border-bottom:12px solid var(--black);
  }
  .masthead{
    grid-column:1/3;
    display:flex;
    justify-content:space-between;
    align-items:baseline;
    padding:1.2rem 2rem;
    border-bottom:12px solid var(--black);
    background:var(--white);
  }
  .masthead h1{
    font-size:clamp(1.1rem,2.4vw,1.7rem);
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.06em;
  }
  .masthead .year{
    font-size:clamp(1rem,2vw,1.4rem);
    font-weight:500;
  }
  /* the composition itself, drawn in CSS */
  .painting{
    grid-column:1/3;
    display:grid;
    grid-template-columns:5fr 7fr 4fr;
    grid-template-rows:7fr 3fr 4fr;
    gap:12px;
    background:var(--black);
    padding:12px;
    margin:2.5rem;
  }
  .painting div{background:var(--white)}
  .painting .red{grid-column:3;grid-row:1;background:var(--red)}
  .painting .blue{grid-column:1;grid-row:3;background:var(--blue)}
  .painting .yellow{grid-column:3;grid-row:3;background:var(--yellow)}

  /* ---------- sections ---------- */
  main{
    display:grid;
    grid-template-columns:1fr 1fr 1fr;
    border-bottom:12px solid var(--black);
  }
  section{
    padding:3rem 2.5rem;
    border-right:12px solid var(--black);
  }
  section:last-child{border-right:none}
  section h2{
    font-size:1.05rem;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.08em;
    margin-bottom:1.2rem;
    display:flex;
    align-items:center;
    gap:.7rem;
  }
  .chip{width:1.1rem;height:1.1rem;display:inline-block;flex:none}
  .chip.red{background:var(--red)}
  .chip.blue{background:var(--blue)}
  .chip.yellow{background:var(--yellow)}
  section p{font-size:1rem;margin-bottom:1rem}
  section p:last-child{margin-bottom:0}
  .big{
    font-size:clamp(1.6rem,3vw,2.4rem);
    font-weight:700;
    line-height:1.2;
    margin-bottom:1rem;
  }

  /* ---------- footer: invitation ---------- */
  footer{
    display:grid;
    grid-template-columns:2fr 1fr;
  }
  footer .invite{
    padding:3rem 2.5rem;
    border-right:12px solid var(--black);
  }
  footer .invite h2{
    font-size:1.05rem;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.08em;
    margin-bottom:1rem;
  }
  footer .invite p{margin-bottom:1.5rem;max-width:46ch}
  a.read{
    display:inline-block;
    background:var(--black);
    color:var(--white);
    text-decoration:none;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.06em;
    padding:1rem 1.8rem;
    border:4px solid var(--black);
  }
  a.read:hover{background:var(--red);border-color:var(--red)}
  footer .swatches{
    display:grid;
    grid-template-rows:1fr 1fr 1fr;
  }
  footer .swatches div{min-height:4.5rem}
  footer .swatches .s-red{background:var(--red)}
  footer .swatches .s-blue{background:var(--blue)}
  footer .swatches .s-yellow{background:var(--yellow)}

